var e=[{slug:`ai-response-evaluation`,number:`01`,title:`AI response evaluation`,short:`Rank, score and critique model outputs against clear, project-specific rubrics.`,problem:`Model teams need preference and evaluation data that reflects real human judgment—not inconsistent clicks. We design calibrated review programmes that make response quality measurable and actionable.`,formats:[`Side-by-side response pairs`,`Rubric scores`,`Written critiques`,`Factuality checks`,`Instruction-following labels`],qualifications:[`Subject-matter knowledge`,`Critical reading`,`Evidence-based writing`,`Project-specific calibration`],workflow:[`Define evaluation dimensions`,`Build and test the rubric`,`Qualify and calibrate evaluators`,`Run production with review sampling`,`Deliver structured data and findings`],controls:[`Gold-standard tasks`,`Inter-rater checks`,`Reviewer escalation`,`Performance monitoring`,`Dataset-level validation`],deliverables:[`Preference datasets`,`Scored model outputs`,`Critique datasets`,`Quality summaries`,`Issue and ambiguity logs`],related:[`rlhf-services`,`model-safety-quality-testing`,`prompt-answer-creation`],faqs:[{question:`Can you work with our existing rubric?`,answer:`Yes. We can operationalise an existing rubric, test it for ambiguity and build calibration examples before production begins.`},{question:`How do you manage subjective judgments?`,answer:`We use anchored examples, evaluator calibration, agreement checks and an escalation path for genuinely ambiguous cases.`}]},{slug:`data-annotation-labelling`,number:`02`,title:`Data annotation & labelling`,short:`Create clean, consistent labels across text, image, audio, video and structured datasets.`,problem:`Annotation quality drifts when instructions, contributor selection and review are treated separately. We manage them as one controlled production system.`,formats:[`Text and conversation`,`Image and video`,`Audio and transcription`,`Structured records`,`Existing datasets for correction`],qualifications:[`Language proficiency`,`Domain knowledge`,`Visual or audio attention`,`Tool-specific training`],workflow:[`Inspect source data`,`Define taxonomy and edge cases`,`Pilot and calibrate`,`Annotate in controlled batches`,`Review, correct and export`],controls:[`Schema validation`,`Consensus or review sampling`,`Hidden quality tasks`,`Edge-case escalation`,`Version-controlled guidance`],deliverables:[`Labelled datasets`,`Corrected datasets`,`Annotation guidelines`,`Quality reports`,`Exception logs`],related:[`ai-response-evaluation`,`expert-ai-training-tasks`,`freelance-workforce-management`],faqs:[{question:`Which annotation tools do you support?`,answer:`We can work in a client-provided environment or agree a suitable tool during scoping. Tool access and data handling are documented before onboarding.`},{question:`Can you improve an existing dataset?`,answer:`Yes. We can audit a sample, identify recurring failure modes and run targeted correction or relabelling.`}]},{slug:`rlhf-services`,number:`03`,title:`RLHF services`,short:`Managed human-preference workflows for ranking, scoring, feedback and critique generation.`,problem:`RLHF programmes depend on reliable human judgment at scale. We combine evaluator selection, calibration, task operations and performance control into one accountable delivery model.`,formats:[`Preference pairs`,`Scalar ratings`,`Rubric assessments`,`Written feedback`,`Critiques and revisions`],qualifications:[`Analytical reasoning`,`Clear written justification`,`Domain expertise where needed`,`Stable calibration performance`],workflow:[`Design the feedback protocol`,`Create calibration sets`,`Qualify evaluator cohorts`,`Run monitored production`,`Review distributions and outliers`],controls:[`Calibration gates`,`Rater agreement analysis`,`Quality sampling`,`Performance thresholds`,`Contributor replacement process`],deliverables:[`Preference data`,`Scoring datasets`,`Critique and revision data`,`Evaluator performance summaries`,`Quality and issue reports`],related:[`ai-response-evaluation`,`prompt-answer-creation`,`freelance-workforce-management`],faqs:[{question:`Do you support specialist RLHF programmes?`,answer:`Yes, subject to verified talent availability. We can recruit and qualify contributors for coding, mathematics, language and other professional domains.`},{question:`Can you manage an existing contributor pool?`,answer:`Yes. We can add calibration, allocation, monitoring, support and review controls around an existing pool.`}]},{slug:`model-safety-quality-testing`,number:`04`,title:`Model safety & quality testing`,short:`Test model behaviour across policy, harm, bias, hallucination and difficult edge cases.`,problem:`Average-case performance can conceal serious risks. We structure human testing around defined policies, user contexts and adversarial scenarios, with clear evidence for every finding.`,formats:[`Model conversations`,`Adversarial prompts`,`Policy labels`,`Failure taxonomies`,`Multilingual evaluations`],qualifications:[`Policy comprehension`,`Adversarial thinking`,`Cultural and language knowledge`,`Sensitive-content readiness`],workflow:[`Map risk categories`,`Design test scenarios`,`Brief and calibrate testers`,`Run controlled evaluation`,`Triage and report findings`],controls:[`Safety-aware onboarding`,`Clear escalation paths`,`Duplicate and leakage checks`,`Senior review`,`Severity calibration`],deliverables:[`Test suites`,`Structured findings`,`Failure examples`,`Severity and policy labels`,`Coverage summaries`],related:[`ai-response-evaluation`,`prompt-answer-creation`,`expert-ai-training-tasks`],faqs:[{question:`Do you provide security certification?`,answer:`We describe and document the operational controls used for an engagement. Formal certification claims are made only when independently verified.`},{question:`Can testing be multilingual?`,answer:`Yes, where qualified language specialists are available and the policy guidance has been adapted for the target language and context.`}]},{slug:`prompt-answer-creation`,number:`05`,title:`Prompt & answer creation`,short:`Build domain-relevant prompts, reference answers and edited instruction datasets.`,problem:`High-value supervised data requires more than fluent writing. It requires task design, domain grounding, unambiguous instructions and strong editorial review.`,formats:[`Single-turn prompts`,`Multi-turn conversations`,`Reference answers`,`Solution explanations`,`Edited instruction records`],qualifications:[`Domain expertise`,`Instructional writing`,`Research and source checking`,`Editorial precision`],workflow:[`Define task families`,`Create exemplars`,`Qualify authors`,`Produce and review`,`De-duplicate and package`],controls:[`Source requirements`,`Editorial rubrics`,`Plagiarism checks`,`Independent review`,`Dataset consistency audits`],deliverables:[`Prompt datasets`,`Reference answers`,`Conversation datasets`,`Edited records`,`Guidelines and quality notes`],related:[`expert-ai-training-tasks`,`ai-response-evaluation`,`rlhf-services`],faqs:[{question:`Can you create domain-specific data?`,answer:`Yes, after confirming the required expertise, source rules and review model. Claims are limited to domains for which suitable specialists can be recruited and qualified.`},{question:`Do you request hidden reasoning from contributors?`,answer:`We design solution explanations that are useful and appropriate for the task without requiring disclosure of private chain-of-thought.`}]},{slug:`expert-ai-training-tasks`,number:`06`,title:`Expert AI training tasks`,short:`Bring coding, mathematics, language and professional-domain judgment into model training.`,problem:`Specialist models need contributors who can recognise subtle errors and create genuinely useful examples. We recruit for the task, verify skill and continuously monitor performance.`,formats:[`Code and tests`,`Mathematical problems`,`Translation and localisation`,`Technical reviews`,`Research and source checks`],qualifications:[`Verified discipline knowledge`,`Task-specific assessment`,`Communication quality`,`Tool and source discipline`],workflow:[`Define expertise levels`,`Source and assess specialists`,`Train on project conventions`,`Allocate by demonstrated skill`,`Review and score output`],controls:[`Skills testing`,`Blind calibration`,`Expert review`,`Performance bands`,`Removal and replacement rules`],deliverables:[`Expert-created datasets`,`Reviewed model outputs`,`Code and tests`,`Localised content`,`Research notes and citations`],related:[`prompt-answer-creation`,`model-safety-quality-testing`,`freelance-workforce-management`],faqs:[{question:`Which expert domains are available?`,answer:`Initial focus areas include software engineering, mathematics and language work. Additional domains are confirmed project by project based on verified talent availability.`},{question:`How do you verify expertise?`,answer:`We combine profile review with practical assessments, calibration work and monitored production performance.`}]},{slug:`freelance-workforce-management`,number:`07`,title:`Freelance workforce management`,short:`Recruit, qualify, onboard, allocate and support specialist contributors under one managed programme.`,problem:`A large contributor pool is not the same as a productive workforce. We manage the operational layer between talent sourcing and quality-assured delivery.`,formats:[`Dedicated project teams`,`Specialist cohorts`,`Flexible production pools`,`Review teams`,`Multilingual groups`],qualifications:[`Identity and profile review`,`Skill assessments`,`Project-specific calibration`,`Ongoing performance standards`],workflow:[`Build the talent profile`,`Source and screen`,`Assess and onboard`,`Allocate and support`,`Monitor, pay and improve`],controls:[`Role-based access`,`Qualification gates`,`Attendance and output monitoring`,`Quality thresholds`,`Contributor replacement`],deliverables:[`Qualified contributor cohorts`,`Onboarding records`,`Allocation plans`,`Performance reporting`,`Contributor support operations`],related:[`rlhf-services`,`data-annotation-labelling`,`expert-ai-training-tasks`],faqs:[{question:`Is ScaleWorkAgency a freelance marketplace?`,answer:`No. Contributors are recruited and qualified for managed programmes. Clients work with an accountable delivery team rather than purchasing directly from an open marketplace.`},{question:`Can workforce location be restricted?`,answer:`Yes. Regional, language and access restrictions can be defined during scoping and enforced through contributor selection and project access rules.`}]}],t=[{title:`Generative AI`,text:`Preference, evaluation and supervised datasets for models that generate useful, relevant responses.`},{title:`Software engineering`,text:`Code review, debugging, test creation and technical evaluation with qualified developers.`},{title:`Language models`,text:`Multilingual evaluation, localisation, intent work and culturally informed quality review.`},{title:`Mathematics`,text:`Problem creation, solution verification and reasoning-quality assessment by capable specialists.`},{title:`Customer support AI`,text:`Conversation labelling, policy adherence, tone review and realistic support scenarios.`},{title:`Safety evaluation`,text:`Policy testing, red teaming and structured identification of harmful or unreliable behaviour.`}],n=[{slug:`human-evaluation-ai-models`,category:`Evaluation`,title:`How human evaluation improves AI models`,excerpt:`A practical look at rubrics, calibration and the signals model teams can actually use.`},{slug:`quality-control-data-annotation`,category:`Quality`,title:`Quality control for AI data annotation`,excerpt:`Why good guidelines are only the beginning—and how review systems prevent drift.`},{slug:`selecting-training-data-partner`,category:`Procurement`,title:`Selecting an AI training data partner`,excerpt:`The questions that reveal how a provider manages people, data, risk and accountability.`}];export{n,e as r,t};